1	//! Prompt mode: prompts, compiled on demand from Piton, are sent to a local
2	//! coding harness as tasks, and each task's output is shown until it finishes.
3	//!
4	//! The latest task heads the view: its status as a coloured label, the hidden
5	//! anchor it was compiled from, and the compiled prompt the harness received.
6	//! Its output fills the space beneath, one table row per thing the harness
7	//! did (its text, each tool call, any error), with the kind of each as a
8	//! badge. A small row, always shown above the header, expands into a scrollable
9	//! accordion of every task sent, each of which opens onto its own output. A file opened
10	//! from the project tree splits the view, taking half of its width; the chat
11	//! input is never split.
12	//!
13	//! Prompts sent while the harness works wait in a queue, saved with the
14	//! project (see [`crate::prompt_queue`]), listed along the bottom of the view.
15	//!
16	//! Every task is saved with the project too (see [`crate::prompt_history`]),
17	//! and opening the project brings back the tasks sent before.
18	
19	use std::cell::Cell;
20	use std::path::{Path, PathBuf};
21	use std::rc::Rc;
22	use std::sync::Arc;
23	
24	use anyhow::Result;
25	use futures::StreamExt as _;
26	use gpui_kit::assets::IconName;
27	use gpui_kit::base::ElementExt as _;
28	use gpui_kit::component::accordion::Accordion;
29	use gpui_kit::component::button::{Button, ButtonVariants as _};
30	use gpui_kit::component::label::Label;
31	use gpui_kit::component::notification::Notification;
32	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
33	use gpui_kit::component::spinner::Spinner;
34	use gpui_kit::component::switch::Switch;
35	use gpui_kit::component::table::{Table, TableBody, TableCell, TableHead, TableHeader, TableRow};
36	use gpui_kit::component::tag::Tag;
37	use gpui_kit::component::text::{TextView, TextViewStyle};
38	use gpui_kit::component::{
39	    ActiveTheme as _, ColorName, Icon, Sizable as _, StyledExt as _, h_flex, v_flex,
40	};
41	use gpui_kit::component::{Disableable as _, WindowExt as _};
42	use gpui_kit::prelude::FluentBuilder as _;
43	use gpui_kit::*;
44	
45	use crate::chat_input::{ChatInput, SendMode, Submit};
46	use crate::file_link::{self, OpenFile};
47	use crate::file_view::{CloseFile, FileView, OpenDefinition};
48	use crate::harness::{self, HarnessEvent};
49	use crate::harness_run::{HarnessRun, HarnessRuns};
50	use crate::hidden_anchor::{self, HiddenAnchor};
51	use crate::markdown;
52	use crate::project_directory::ProjectDirectory;
53	use crate::prompt_history::{self, RunRecord, SavedPrompt};
54	use crate::prompt_queue::{self, QueuedPrompt};
55	use crate::shell_format;
56	
57	/// The share of the width an opened file takes from the task view.
58	const FILE_SHARE: f32 = 0.5;
59	
60	/// The narrowest either side of the file split can be dragged.
61	const MIN_SPLIT_WIDTH: Pixels = px(160.);
62	
63	/// The tallest the expanded queue gets before it scrolls.
64	const MAX_QUEUE_HEIGHT: Pixels = px(240.);
65	
66	/// The tallest the compiled prompt in the header gets before it scrolls.
67	const MAX_PROMPT_HEIGHT: Pixels = px(160.);
68	
69	/// The widths of the output table's badge and status columns; the detail
70	/// column takes the rest.
71	const KIND_WIDTH: Pixels = px(130.);
72	const STATUS_WIDTH: Pixels = px(110.);
73	
74	/// A prompt in the queue. Its hidden anchor is resolved and saved in the
75	/// background just after it is queued; until then it cannot be sent.
76	struct QueueItem {
77	    id: usize,
78	    text: SharedString,
79	    saved: Option<QueuedPrompt>,
80	}
81	
82	/// A prompt on its way to the harness.
83	enum Sending {
84	    /// Typed and sent straight away, in a mode.
85	    Now(SendMode),
86	    /// Out of the queue, saved with its anchor.
87	    Queued(QueuedPrompt),
88	}
89	
90	/// A prompt sent to the harness, and what the harness did with it.
91	struct PromptTask {
92	    /// The prompt as typed, shown until it compiles.
93	    text: SharedString,
94	    compiled: Option<Compiled>,
95	    reply: Reply,
96	    status: TaskStatus,
97	}
98	
99	/// A sent prompt once compiled.
100	struct Compiled {
101	    /// The name of the hidden anchor it was compiled from.
102	    anchor: SharedString,
103	    markdown: String,
104	}
105	
106	#[derive(Clone, Copy, Debug, PartialEq)]
107	enum TaskStatus {
108	    Compiling,
109	    Running,
110	    Done,
111	    Failed,
112	    /// From the history, with no record of what came of it.
113	    Unrecorded,
114	}
115	
116	impl TaskStatus {
117	    fn label(self) -> &'static str {
118	        match self {
119	            Self::Compiling => "Compiling",
120	            Self::Running => "Running",
121	            Self::Done => "Done",
122	            Self::Failed => "Failed",
123	            Self::Unrecorded => "Not recorded",
124	        }
125	    }
126	
127	    fn is_active(self) -> bool {
128	        matches!(self, Self::Compiling | Self::Running)
129	    }
130	
131	    /// A label in the status's colour, with the status spelled out. Uses the
132	    /// palette colours, like the output badges, as the theme's solid status
133	    /// colours are unreadable in dark mode.
134	    fn tag(self) -> Tag {
135	        Tag::color(match self {
136	            Self::Compiling => ColorName::Cyan,
137	            Self::Running => ColorName::Yellow,
138	            Self::Done => ColorName::Green,
139	            Self::Failed => ColorName::Red,
140	            Self::Unrecorded => ColorName::Gray,
141	        })
142	        .text_sm()
143	        .child(self.label())
144	    }
145	}
146	
147	impl PromptTask {
148	    fn new(text: SharedString) -> Self {
149	        Self {
150	            text,
151	            compiled: None,
152	            reply: Reply::default(),
153	            status: TaskStatus::Compiling,
154	        }
155	    }
156	
157	    /// A task from the history, as it ended: its run's output is replayed
158	    /// through the harness's parser.
159	    fn restore(saved: SavedPrompt) -> Self {
160	        let mut task = Self::new(saved.text.into());
161	        let Some(record) = saved.record else {
162	            task.reply.done = true;
163	            task.status = TaskStatus::Unrecorded;
164	            return task;
165	        };
166	        if let Some(markdown) = record.user_prompt {
167	            task.set_compiled(Compiled {
168	                anchor: saved.anchor.name().to_string().into(),
169	                markdown,
170	            });
171	        }
172	        for event in record.output.iter().flat_map(harness::parse) {
173	            task.apply(event);
174	        }
175	        if let Some(error) = record.error {
176	            task.apply(HarnessEvent::Failed(error));
177	        }
178	        task.end();
179	        task
180	    }
181	
182	    fn set_compiled(&mut self, compiled: Compiled) {
183	        self.compiled = Some(compiled);
184	        self.status = TaskStatus::Running;
185	    }
186	
187	    /// Folds a harness event into the task's output and status.
188	    fn apply(&mut self, event: HarnessEvent) {
189	        match self.reply.apply(event) {
190	            Some(error) => self.fail(error),
191	            None if self.reply.done && self.status == TaskStatus::Running => {
192	                self.status = TaskStatus::Done
193	            }
194	            None => {}
195	        }
196	    }
197	
198	    fn fail(&mut self, error: String) {
199	        self.reply.parts.push(ReplyPart::Error(error));
200	        self.status = TaskStatus::Failed;
201	    }
202	
203	    /// The run is over. One that ended without a result, as when the harness
204	    /// was stopped, failed, and nothing still running in it finished.
205	    fn end(&mut self) {
206	        if self.reply.done {
207	            return;
208	        }
209	        self.reply.done = true;
210	        self.reply.settle_tools(ToolState::Failed);
