1386	/// `code` as a fenced markdown code block, its fence longer than any run of
1387	/// backticks inside it.
1388	fn code_block(language: &str, code: &str) -> String {
1389	    let longest = code.split(|c| c != '`').map(str::len).max().unwrap_or(0);
