1394	/// `text` with the project directory written relative to it: paths inside the
1395	/// directory lose its path, and the directory itself reads `.`. A path that
1396	/// only starts with the same characters, like a sibling directory, is kept.
1397	fn relative_to_project(text: &str, project_dir: Option<&Path>) -> String {
1398	    let Some(dir) = project_dir
1399	        .and_then(Path::to_str)
1400	        .map(|dir| dir.trim_end_matches('/'))
1401	        .filter(|dir| !dir.is_empty())
1402	    else {
1403	        return text.to_string();
1404	    };
1405	    let is_path_char = |c: char| c.is_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | '~');
1406	    let ends_path = |rest: &str| rest.chars().next().is_none_or(|c| !is_path_char(c));
1407	
1408	    let mut out = String::with_capacity(text.len());
1409	    let mut rest = text;
1410	    while let Some(at) = rest.find(dir) {
1411	        out.push_str(&rest[..at]);
1412	        let after = &rest[at + dir.len()..];
1413	        let starts_path = out.chars().last().is_none_or(|c| !is_path_char(c));
1414	        rest = if starts_path && ends_path(after) {
1415	            out.push('.');
1416	            after
1417	        } else if starts_path && after.starts_with('/') {
1418	            let inside = &after[1..];
1419	            if ends_path(inside) {
1420	                out.push('.');
1421	            }
1422	            inside
1423	        } else {
1424	            out.push_str(dir);
1425	            after
1426	        };
1427	    }
1428	    out.push_str(rest);
1429	    out
1430	}
