                }
            });
        })
        .unwrap();

        cx.wait_for(handle, Duration::from_secs(1), |window, _| {
            window.try_find("history-toggle").is_some()
        })
        .await;
        cx.update_window(handle, |_, window, cx| window.click("history-toggle", cx))
