                && window.try_find(("history-task", 1usize)).is_some()
                && window.try_find("task-output").is_none()
        })
        .await;

        cx.update_window(handle, |_, window, cx| {
            window.click(("history-task", 0usize), cx)
        })
        .unwrap();
